def is_synchronous_protocol(protocol_behavior):
    if protocol_behavior.new_mode_tasks_start_condition == "all_old_mode_tasks_completed":
        return True
    else:
        return False

def has_periodicity_protocol(protocol_features):
    if protocol_features.supports_mode_independent_tasks:
        return True
    else:
        return False

def is_job_active(job, current_time_t):
    if job.release_time <= current_time_t and not job.is_completed:
        return True
    else:
        return False

def can_task_release_jobs(task):
    return task.is_enabled

def enable_task(task):
    task.is_enabled = True

def disable_task(task):
    task.is_enabled = False

import math

def calculate_dbf_single_task(task_k, interval_length_t):
    if interval_length_t < task_k.D:
        return 0
    num_jobs = math.floor((interval_length_t - task_k.D) / task_k.T) + 1
    return num_jobs * task_k.C

def calculate_lambda_max(task_set_tau_i):
    max_density = 0
    for task_i_k in task_set_tau_i:
        current_density = calculate_task_density(task_i_k) # Assumes calculate_task_density from Item 5
        if current_density > max_density:
            max_density = current_density
    return max_density

def calculate_lambda_sum(task_set_tau_i):
    total_density = 0
    for task_i_k in task_set_tau_i:
        total_density += calculate_task_density(task_i_k) # Assumes calculate_task_density from Item 5
    return total_density

def calculate_dbf_task_set(task_set_tau_i, interval_length_t):
    total_dbf = 0
    for task_i_k in task_set_tau_i:
        total_dbf += calculate_dbf_single_task(task_i_k, interval_length_t) # Assumes calculate_dbf_single_task from Item 6
    return total_dbf

def calculate_ff_dbf_task_set(task_set_tau_i, interval_length_t, processor_speed_sigma):
    total_ff_dbf = 0
    for task_i_k in task_set_tau_i:
        total_ff_dbf += calculate_ff_dbf_single_task(task_i_k, interval_length_t, processor_speed_sigma) # Assumes calculate_ff_dbf_single_task from Item 7
    return total_ff_dbf

def calculate_ff_load(task_set_tau_i, processor_speed_sigma, max_interval_t):
    max_ff_load = 0
    for t in range(1, max_interval_t + 1): # Example range
        current_ff_dbf = calculate_ff_dbf_task_set(task_set_tau_i, t, processor_speed_sigma) # Assumes calculate_ff_dbf_task_set from Item 11
        if t > 0:
            current_ff_load = current_ff_dbf / t
            if current_ff_load > max_ff_load:
                max_ff_load = current_ff_load
    return max_ff_load

def is_protocol_valid(multimode_system_tau, platform_pi, protocol_P):
    for old_mode_M_i in multimode_system_tau.modes:
        for new_mode_M_j in multimode_system_tau.modes:
            if old_mode_M_i == new_mode_M_j:
                continue # No transition

            for task_j_k in new_mode_M_j.ms_tasks:
                # Check if protocol_P ensures task_j_k is enabled by its transition deadline
                # This check would involve specific logic of protocol_P
                if not protocol_P.guarantees_transition_deadline(task_j_k, old_mode_M_i, new_mode_M_j):
                    return False
    return True

def calculate_D_max(mode_i):
    max_deadline = 0
    for task_i_k in mode_i.ms_tasks:
        if task_i_k.D > max_deadline:
            max_deadline = task_i_k.D
    return max_deadline

def check_sm_mdo_validity(multimode_system_tau):
    for mode_i in multimode_system_tau.modes:
        D_max_i = calculate_D_max(mode_i) # Assumes calculate_D_max from Item 17

        min_transition_deadline_for_all_new_modes = float('inf')
        for mode_j in multimode_system_tau.modes:
            if mode_i == mode_j:
                continue

            min_D_j_r_Mi = float('inf')
            for task_j_r in mode_j.ms_tasks:
                # Assuming task_j_r.transition_deadline_from_Mi is D_j_r(M_i)
                if task_j_r.transition_deadline_from_Mi < min_D_j_r_Mi:
                    min_D_j_r_Mi = task_j_r.transition_deadline_from_Mi

            if min_D_j_r_Mi < min_transition_deadline_for_all_new_modes:
                min_transition_deadline_for_all_new_modes = min_D_j_r_Mi

        if D_max_i > min_transition_deadline_for_all_new_modes:
            return False # Validity condition violated
    return True # Protocol is valid

def is_gfb_schedulable(task_set_tau, m_processors):
    total_density = calculate_lambda_sum(task_set_tau) # Assumes calculate_lambda_sum from Item 9
    max_density = calculate_lambda_max(task_set_tau) # Assumes calculate_lambda_max from Item 8

    if total_density - max_density <= m_processors:
        return True
    else:
        return False
